import * as React from "react"
import { Link } from "gatsby"
import Header from "../../components/Header"
import Seo from "../../components/Seo"
import PlanLimits from "../../components/admin/PlanLimits"
import * as s from "../../components/admin/Admin.module.css"

/**
 * Usage limits, on their own page — FCS-073(b).
 * ============================================================================
 * Its own page rather than a card on /admin, because it is a different kind
 * of job. /admin is where somebody goes to fix one customer who cannot log
 * in; this is where somebody decides what every customer on a plan gets.
 * Those are not the same errand and they do not want to be scrolled past
 * each other.
 *
 * The grid gates itself: PlanLimits asks the server, and an account without
 * an admin row is told so plainly rather than being shown an empty table it
 * cannot save.
 */

const LimitsPage = () => (
  <>
    <Header />
    <main className={s.page} data-print="hide">
      <div className="container">
        <div className={s.head}>
          <h1 className={s.title}>Plan limits</h1>
        </div>
        <p className={s.lead}>
          What each plan may use in a month. Set here, not in a deploy — a cap is a commercial
          decision, and changing one should not need a release.
        </p>

        <div className={s.card}>
          <PlanLimits />
        </div>

        <p className={s.lead}>
          <Link to="/admin/">Back to Admin</Link>
        </p>
      </div>
    </main>
  </>
)

export const Head = () => (
  <Seo title="Plan limits" description="Internal tools." noindex />
)

export default LimitsPage
