import * as React from "react"
import project from "../../../project.json"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"
import * as s from "./PlanLimits.module.css"

/**
 * What each plan may use — FCS-073(b).
 * ============================================================================
 * A grid: one row per thing that can be capped, one column per plan, one box
 * per decision. The shape of the screen is the shape of the data, so there is
 * nothing to learn — "QR codes, Premium, 10" is three glances.
 *
 * ── EMPTY MEANS UNLIMITED, AND THE BOX SAYS SO ─────────────────────────────
 * The hardest thing to get right here is the difference between "no cap" and
 * "a cap of none", which a single number field cannot express on its own. So
 * an empty box shows the word Unlimited as its placeholder, and 0 is a real,
 * saved, different answer. Every screen that reads these has to honour the
 * same distinction, which is why the column exists as a nullable integer
 * rather than a count with a magic zero.
 *
 * ── IT SAVES ON BLUR, NOT ON EVERY KEYSTROKE ───────────────────────────────
 * Typing "10" passes through "1", and a save on every keystroke would briefly
 * cap premium at one. The write happens when the box is left or Enter is
 * pressed, and only when the value actually changed.
 *
 * ── A FAILED SAVE PUTS THE OLD NUMBER BACK ─────────────────────────────────
 * Same rule as the template board: the grid must never show a number the
 * database does not hold. If the write fails the cell reverts and says why.
 */

const PLANS = [
  { id: "free", label: "Free" },
  { id: "premium", label: "Premium" },
  { id: "leads", label: "Lead Generation" },
]

const FEATURES = project.limits?.features || []

const call = async body => {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token

  const res = await fetch(apiUrl("admin-limits"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
    },
    body: JSON.stringify(body),
  })
  return { ok: res.ok, status: res.status, body: await res.json().catch(() => ({})) }
}

/** "" for unlimited, otherwise the number as a string. */
const asText = value => (value === null || value === undefined ? "" : String(value))

const PlanLimits = () => {
  const [limits, setLimits] = React.useState(null)
  /* What one use costs in credits, per plan and feature — FCS-087. Stored
     beside the cap but edited and saved on its own, so pricing a feature
     never rewrites its limit and the reverse. */
  const [credits, setCredits] = React.useState({})
  const [draft, setDraft] = React.useState({})
  const [error, setError] = React.useState("")
  const [denied, setDenied] = React.useState(false)
  const [signedOut, setSignedOut] = React.useState(false)
  const [canEdit, setCanEdit] = React.useState(false)
  const [saving, setSaving] = React.useState("")
  const [saved, setSaved] = React.useState("")

  const load = React.useCallback(async () => {
    const res = await call({ action: "list" })
    if (!res.ok) {
      /* 401 and 403 are different answers and deserve different sentences:
         one means log in, the other means this is not your screen. */
      setSignedOut(res.status === 401)
      setDenied(res.status === 403)
      setError(
        res.status === 401 || res.status === 403
          ? ""
          : res.body.message || `Could not load the limits (HTTP ${res.status}).`
      )
      return
    }
    /* Reading is open to any account, so a 200 is not permission to edit. */
    if (!res.body.canEdit) {
      setDenied(true)
      return
    }
    setCanEdit(true)
    const next = {}
    const priced = {}
    for (const row of res.body.limits || []) {
      next[`${row.plan}:${row.feature}`] = row.monthly_limit
      priced[`${row.plan}:${row.feature}`] = row.credits_per_use
    }
    setLimits(next)
    setCredits(priced)
    setDraft({
      ...Object.fromEntries(Object.entries(next).map(([k, v]) => [k, asText(v)])),
      ...Object.fromEntries(Object.entries(priced).map(([k, v]) => [`${k}#c`, asText(v)])),
    })
  }, [])

  React.useEffect(() => {
    load()
  }, [load])

  /* `field` is "limit" or "credits". Same rules for both: a whole number of
     0 or more, empty means unset, 0 is a real answer, and a failed save puts
     the old value back so the grid never shows something the database does
     not hold. */
  const commit = async (plan, feature, field = "limit") => {
    const key = `${plan}:${feature}`
    const slot = field === "credits" ? `${key}#c` : key
    const store = field === "credits" ? credits : limits
    const put = field === "credits" ? setCredits : setLimits

    const text = (draft[slot] ?? "").trim()
    const before = store[key] ?? null
    const after = text === "" ? null : Number(text)

    if (text !== "" && (!Number.isInteger(after) || after < 0)) {
      setError("That is a whole number of 0 or more. Leave it empty if it is not set.")
      setDraft(d => ({ ...d, [slot]: asText(before) }))
      return
    }
    if (after === before) return

    setSaving(slot)
    setError("")
    put(l => ({ ...l, [key]: after }))

    const res = await call({ action: "set", plan, feature, [field]: after })
    setSaving("")

    if (!res.ok) {
      put(l => ({ ...l, [key]: before }))
      setDraft(d => ({ ...d, [slot]: asText(before) }))
      setError(res.body.message || "That did not save.")
      return
    }

    setSaved(slot)
    setTimeout(() => setSaved(k => (k === slot ? "" : k)), 1400)
  }

  if (signedOut) {
    return (
      <div className={s.wrap}>
        <h2 className={s.title}>Usage limits</h2>
        <p className={s.note}>Log in with an administrator account to see the limits.</p>
      </div>
    )
  }

  if (denied) {
    return (
      <div className={s.wrap}>
        <h2 className={s.title}>Usage limits</h2>
        <p className={s.note}>
          This account is not an administrator, so the limits cannot be changed here.
        </p>
      </div>
    )
  }

  if (error && !limits) {
    return (
      <div className={s.wrap}>
        <p className={s.error}>{error}</p>
        <button type="button" className={s.ghost} onClick={load}>
          Try again
        </button>
      </div>
    )
  }

  if (!limits) return <p className={s.note}>Loading the limits…</p>

  const set = Object.values(limits).filter(v => v !== null && v !== undefined).length

  return (
    <div className={s.wrap}>
      <div className={s.head}>
        <div>
          <h2 className={s.title}>Usage limits</h2>
          <p className={s.note}>
            What each plan may use. Leave a box empty for unlimited; 0 means none at all. Changes
            save when you leave the box.
          </p>
        </div>
        <span className={s.count}>
          {set} cap{set === 1 ? "" : "s"} set
        </span>
      </div>

      {error ? <p className={s.error}>{error}</p> : null}

      <div className={s.scroll}>
        <table className={s.table}>
          <thead>
            <tr>
              <th scope="col" className={s.rowHead}>
                Feature
              </th>
              {PLANS.map(plan => (
                <th scope="col" key={plan.id} className={s.planHead}>
                  {plan.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {FEATURES.map(feature => (
              <tr key={feature.id}>
                <th scope="row" className={s.rowHead}>
                  <span className={s.featureName}>{feature.name}</span>
                  <span className={s.unit}>{feature.unit}</span>
                </th>
                {PLANS.map(plan => {
                  const key = `${plan.id}:${feature.id}`
                  return (
                    <td key={plan.id} className={s.cell}>
                      <input
                        className={s.input}
                        type="number"
                        min="0"
                        step="1"
                        inputMode="numeric"
                        placeholder="Unlimited"
                        aria-label={`${feature.name}, ${plan.label}`}
                        value={draft[key] ?? ""}
                        data-cell={key}
                        data-state={
                          saving === key ? "saving" : saved === key ? "saved" : undefined
                        }
                        onChange={event =>
                          setDraft(d => ({ ...d, [key]: event.target.value }))
                        }
                        disabled={!canEdit}
                        onBlur={() => commit(plan.id, feature.id, "limit")}
                        onKeyDown={event => {
                          if (event.key === "Enter") event.currentTarget.blur()
                        }}
                      />
                      {/* FCS-087: what one use costs, in credits. Only a
                          value for now — nothing is deducted yet. */}
                      <label className={s.creditRow}>
                        <span>credits</span>
                        <input
                          className={`${s.input} ${s.creditInput}`}
                          type="number"
                          min="0"
                          step="1"
                          inputMode="numeric"
                          placeholder="—"
                          aria-label={`${feature.name}, ${plan.label}, credits per use`}
                          value={draft[`${key}#c`] ?? ""}
                          data-credit-cell={key}
                          data-state={
                            saving === `${key}#c` ? "saving" : saved === `${key}#c` ? "saved" : undefined
                          }
                          onChange={event =>
                            setDraft(d => ({ ...d, [`${key}#c`]: event.target.value }))
                          }
                          disabled={!canEdit}
                          onBlur={() => commit(plan.id, feature.id, "credits")}
                          onKeyDown={event => {
                            if (event.key === "Enter") event.currentTarget.blur()
                          }}
                        />
                      </label>
                    </td>
                  )
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p className={s.note}>
        Nothing is capped until a number is put in. That is deliberate — switching this on should
        not quietly start refusing work to somebody who has already paid. The one exception is
        Trackable QR codes, which starts closed on the Free plan because it is a paid feature.
        The small <strong>credits</strong> box beside each cap is what one use costs; it is only a
        value for now and nothing is charged.
      </p>
    </div>
  )
}

export default PlanLimits
